  const dur = (h, m) => [`${h ? `${h} hour${h === 1 ? '' : 's'}` : ''}${h && m ? ' ' : ''}${m ? `${m} minutes` : ''}`, `${h ? `${h} jam` : ''}${h && m ? ' ' : ''}${m ? `${m} minit` : ''}`];
  const dur2 = (t) => { const m = Math.round(t * 60); return dur(Math.floor(m / 60), m % 60); };
